),
numerados AS (
  SELECT id_usuario, ROW_NUMBER() OVER (ORDER BY id_usuario) AS rn
  FROM novos_usuarios
)
INSERT INTO biblioteca_jogos.assinaturas (id_usuario, plano, data_inicio, data_expiracao)
SELECT
  id_usuario,
  CASE (rn % 3)
    WHEN 0 THEN 'gratuito'
    WHEN 1 THEN 'premium'
    ELSE 'premium_anual'
  END AS plano,
  CURRENT_DATE - ((rn % 700))::int AS data_inicio,
  CASE WHEN rn % 3 = 0 THEN NULL
       ELSE CURRENT_DATE + (((rn * 7) % 365) + 30)::int
  END AS data_expiracao
FROM numerados;

COMMIT;
